#!/usr/bin/env node
/**
 * generate-readme-product-table.js
 *
 * Regenerates the "Product Portfolio → Domain Packs" marketing table in
 * README.md from a single source of truth: scripts/portfolio.config.json,
 * cross-checked against the live artifact registry (artifacts/<name>/
 * .replit-artifact/artifact.toml). This prevents the table from drifting when
 * a new domain pack ships as an artifact.
 *
 * The generated block lives between:
 *   <!-- BEGIN: portfolio-table (generated by scripts/generate-readme-product-table.js) -->
 *   ...
 *   <!-- END: portfolio-table -->
 *
 * Modes:
 *   (default)  Write the regenerated table back into README.md.
 *   --check    Do NOT write. Exit 1 if README.md is out of date or if there is
 *              drift between the artifact registry and portfolio.config.json
 *              (e.g. a shippable artifact exists but is not marketed and not
 *              explicitly excluded). Used by CI.
 *
 * Drift rules (--check):
 *   1. README block must match what the script would generate.
 *   2. Every `artifactId` in portfolio.config.json must exist in the registry.
 *   3. Every artifact in the registry must EITHER appear in `domainPacks`
 *      (referenced by artifactId) OR be listed in `excludeArtifacts`.
 *
 * Usage:
 *   node scripts/generate-readme-product-table.js          # write
 *   node scripts/generate-readme-product-table.js --check  # CI gate
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.resolve(__dirname, '..');

const README_PATH = path.join(ROOT, 'README.md');
const CONFIG_PATH = path.join(ROOT, 'scripts', 'portfolio.config.json');
const ARTIFACTS_DIR = path.join(ROOT, 'artifacts');

const BEGIN_MARKER =
  '<!-- BEGIN: portfolio-table (generated by scripts/generate-readme-product-table.js) -->';
const END_MARKER = '<!-- END: portfolio-table -->';

// ─── Tiny TOML reader (top-level scalar keys only) ────────────────────────────
// We only need `id`, `kind`, `title`, `previewPath`. A full TOML parser would be
// overkill and add a dependency.
function readArtifactToml(file) {
  const text = fs.readFileSync(file, 'utf8');
  const out = {};
  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trim();
    // Stop at first table header so we only read top-level scalars.
    if (line.startsWith('[')) break;
    const m = line.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*"([^"]*)"\s*$/);
    if (m) out[m[1]] = m[2];
  }
  return out;
}

function loadRegistry() {
  if (!fs.existsSync(ARTIFACTS_DIR)) return [];
  const entries = [];
  for (const dir of fs.readdirSync(ARTIFACTS_DIR)) {
    const tomlPath = path.join(ARTIFACTS_DIR, dir, '.replit-artifact', 'artifact.toml');
    if (!fs.existsSync(tomlPath)) continue;
    const meta = readArtifactToml(tomlPath);
    if (!meta.id) continue;
    entries.push({
      dir,
      id: meta.id,
      kind: meta.kind || '',
      title: meta.title || dir,
      previewPath: meta.previewPath || '',
    });
  }
  return entries;
}

function loadConfig() {
  const raw = fs.readFileSync(CONFIG_PATH, 'utf8');
  return JSON.parse(raw);
}

function escapePipe(s) {
  return String(s).replace(/\|/g, '\\|');
}

function renderTable(config) {
  const lines = [];
  lines.push('| Product | Domain | Status |');
  lines.push('|---------|--------|--------|');
  for (const row of config.domainPacks) {
    lines.push(
      `| **${escapePipe(row.product)}** | ${escapePipe(row.domain)} | ${escapePipe(row.status)} |`,
    );
  }
  return lines.join('\n');
}

function renderBlock(config) {
  return [BEGIN_MARKER, '', renderTable(config), '', END_MARKER].join('\n');
}

function checkDrift(config, registry) {
  const errors = [];
  const registryIds = new Set(registry.map((r) => r.id));

  // Rule 2: every artifactId in config must exist
  for (const row of config.domainPacks) {
    if (row.artifactId && !registryIds.has(row.artifactId)) {
      errors.push(
        `portfolio.config.json: domainPack "${row.product}" references artifactId "${row.artifactId}" which is not present in the artifact registry.`,
      );
    }
  }

  // Rule 3: every registry artifact must be in domainPacks OR excludeArtifacts
  const referencedIds = new Set(
    config.domainPacks.filter((r) => r.artifactId).map((r) => r.artifactId),
  );
  const excluded = new Set(config.excludeArtifacts || []);
  for (const a of registry) {
    if (referencedIds.has(a.id) || excluded.has(a.id)) continue;
    errors.push(
      `Artifact "${a.id}" (${a.title}) is in the registry but neither listed in domainPacks nor in excludeArtifacts. ` +
        `Add it to scripts/portfolio.config.json (either as a Domain Pack row or in excludeArtifacts).`,
    );
  }

  return errors;
}

function ensureMarkers(readme) {
  const begin = readme.indexOf(BEGIN_MARKER);
  const end = readme.indexOf(END_MARKER);
  if (begin === -1 || end === -1 || end < begin) {
    throw new Error(
      `README.md is missing the portfolio-table markers.\n` +
        `Expected to find:\n  ${BEGIN_MARKER}\n  ...\n  ${END_MARKER}\n` +
        `Add them around the existing Domain Packs table, then re-run.`,
    );
  }
  return { begin, end: end + END_MARKER.length };
}

function spliceBlock(readme, newBlock) {
  const { begin, end } = ensureMarkers(readme);
  return readme.slice(0, begin) + newBlock + readme.slice(end);
}

function main() {
  const checkMode = process.argv.includes('--check');
  const config = loadConfig();
  const registry = loadRegistry();

  const driftErrors = checkDrift(config, registry);

  const readme = fs.readFileSync(README_PATH, 'utf8');
  const newBlock = renderBlock(config);
  const updated = spliceBlock(readme, newBlock);

  if (checkMode) {
    const failures = [...driftErrors];
    if (updated !== readme) {
      failures.push(
        `README.md "Domain Packs" table is out of date. Run \`pnpm readme:portfolio\` to regenerate it.`,
      );
    }
    if (failures.length > 0) {
      console.error('README portfolio drift detected:');
      for (const e of failures) console.error('  - ' + e);
      process.exit(1);
    }
    console.log(
      `OK: README portfolio table is in sync (${config.domainPacks.length} rows, ${registry.length} artifacts in registry).`,
    );
    return;
  }

  // Write mode: surface drift warnings but still rewrite the table.
  if (driftErrors.length > 0) {
    console.warn('Portfolio drift warnings (non-fatal in write mode):');
    for (const e of driftErrors) console.warn('  - ' + e);
  }

  if (updated === readme) {
    console.log('README portfolio table already up to date.');
    return;
  }
  fs.writeFileSync(README_PATH, updated);
  console.log(`Updated README.md portfolio table (${config.domainPacks.length} rows).`);
}

main();
